def tri(n):
    if n < 0:
        return "Input must be non-negative"

    # Initialize the list with base cases
    trib = [1, 3] + [0] * (n - 1)

    for i in range(2, n + 1):
        if i % 2 == 0:
            trib[i] = 1 + int(i / 2)
        else:
            trib[i] = trib[i - 1] + trib[i - 2] + trib[i + 1]

    return trib[:n+1]
```
